// rs::tirfit (core/tools/tirfit.cpp): the fitter recovers a known tyre from curves generated by rs::mf62 (noise-free and with noise) when started from a DIFFERENT tyre, and judges itself on
// held-out loads and slips it never saw. SYNTHETIC data only: no measured tyre data is in the repository (docs/own_tyre_data.md says so).
// Thresholds were fixed before the first run: noise-free Fx / Fy rms <= 1.5 % of the peak, Mz <= 5 %, combined slip <= 4 %, peak force and cornering stiffness within 3 %.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>
#include "harness.hpp"
#include "rs/mf62.hpp"
#include "rs/tirfit.hpp"

namespace {
using namespace rs;

mf62::Output tyre_at(const mf62::Params& p, double fz, double kappa, double alpha, double gamma) {
    mf62::Input in;
    in.fz = fz; in.kappa = kappa; in.alpha = alpha; in.gamma = gamma; in.vx = p.longvl;
    return mf62::evaluate(p, in, mf62::modes_from_use_mode(111));
}

using Grid = tirfit::SweepSpec;

std::vector<tirfit::Sample> synth(const mf62::Params& truth, Grid g, double noise, bool combined_set) {
    g.noise = noise;
    g.combined = combined_set;
    return tirfit::synthetic_sweep(truth, g);
}

struct Errors { double fx = 0, fy = 0, mz = 0, fxc = 0, fyc = 0, peak_fy = 0, peak_fx = 0, c_alpha = 0; };

// held-out points: loads never in the training set, slips inside the data range
Errors validate(const mf62::Params& truth, const mf62::Params& fitted) {
    Errors e;
    double sx = 0, sy = 0, sm = 0, sxc = 0, syc = 0, px = 0, py = 0, pm = 0, pxc = 0, pyc = 0;
    int nx = 0, ny = 0, nxc = 0;
    for (double l : {0.6, 0.9, 1.1, 1.4}) {
        const double fz = l * truth.fnomin;
        for (int i = -24; i <= 24; i += 2) {
            const double k = 0.01 * i;
            const auto a = tyre_at(truth, fz, k, 0, 0), b = tyre_at(fitted, fz, k, 0, 0);
            sx += (a.fx - b.fx) * (a.fx - b.fx); px = std::max(px, std::abs(a.fx)); ++nx;
        }
        for (double gm : {0.0, 0.05}) {
            for (int i = -24; i <= 24; i += 2) {
                const double al = 0.01 * i;
                const auto a = tyre_at(truth, fz, 0, al, gm), b = tyre_at(fitted, fz, 0, al, gm);
                sy += (a.fy - b.fy) * (a.fy - b.fy); py = std::max(py, std::abs(a.fy));
                sm += (a.mz - b.mz) * (a.mz - b.mz); pm = std::max(pm, std::abs(a.mz)); ++ny;
            }
        }
        for (double k : {-0.12, -0.06, 0.06, 0.12})
            for (double al : {-0.1, -0.06, 0.06, 0.1}) {
                const auto a = tyre_at(truth, fz, k, al, 0), b = tyre_at(fitted, fz, k, al, 0);
                sxc += (a.fx - b.fx) * (a.fx - b.fx); pxc = std::max(pxc, std::abs(a.fx));
                syc += (a.fy - b.fy) * (a.fy - b.fy); pyc = std::max(pyc, std::abs(a.fy)); ++nxc;
            }
    }
    e.fx = 100.0 * std::sqrt(sx / nx) / px;
    e.fy = 100.0 * std::sqrt(sy / ny) / py;
    e.mz = 100.0 * std::sqrt(sm / ny) / pm;
    e.fxc = 100.0 * std::sqrt(sxc / nxc) / pxc;
    e.fyc = 100.0 * std::sqrt(syc / nxc) / pyc;
    auto peak = [&](const mf62::Params& p, bool x) {
        double best = 0;
        for (int i = 1; i <= 250; ++i) best = std::max(best, std::abs(x ? tyre_at(p, p.fnomin, i * 0.001, 0, 0).fx : tyre_at(p, p.fnomin, 0, i * 0.001, 0).fy));
        return best;
    };
    e.peak_fy = 100.0 * std::abs(peak(fitted, false) / peak(truth, false) - 1.0);
    e.peak_fx = 100.0 * std::abs(peak(fitted, true) / peak(truth, true) - 1.0);
    auto slope = [&](const mf62::Params& p) { return (tyre_at(p, p.fnomin, 0, 0.002, 0).fy - tyre_at(p, p.fnomin, 0, -0.002, 0).fy) / 0.004; };
    e.c_alpha = 100.0 * std::abs(slope(fitted) / slope(truth) - 1.0);
    return e;
}

void print_errors(const char* tag, const Errors& e) {
    std::printf("         %-34s Fx %.2f %%, Fy %.2f %%, Mz %.2f %%, combined Fx %.2f %% Fy %.2f %% | peak Fy %.2f %%, peak Fx %.2f %%, C_alpha %.2f %%\n", tag, e.fx, e.fy, e.mz, e.fxc, e.fyc, e.peak_fy, e.peak_fx, e.c_alpha);
}

mf62::Params load(const char* file) {
    mf62::Params p;
    std::string err;
    if (!mf62::load_tir_file(test::data_path(std::string("tires/") + file), p, err)) std::printf("         cannot load %s: %s\n", file, err.c_str());
    return p;
}

// a different tyre carrying the geometry the user would give (size, nominal load, pressure): the fit has to supply everything else
mf62::Params start_from(const char* file, const mf62::Params& truth) {
    mf62::Params t = load(file);
    t.fnomin = truth.fnomin; t.unloaded_radius = truth.unloaded_radius; t.width = truth.width; t.aspect_ratio = truth.aspect_ratio; t.rim_radius = truth.rim_radius;
    t.nompres = truth.nompres; t.inflpres = truth.inflpres; t.vertical_stiffness = truth.vertical_stiffness; t.longvl = truth.longvl;
    t.fzmin = truth.fzmin; t.fzmax = truth.fzmax;
    return t;
}

RS_TEST(tirfit_roundtrip) {
    const mf62::Params truth = load("audi_245_40R18_pac2002.tir");
    Grid g;
    g.loads = {0.5, 0.75, 1.0, 1.25, 1.5};
    const std::vector<tirfit::Sample> clean = synth(truth, g, 0.0, true);
    const std::vector<tirfit::Sample> noisy = synth(truth, g, 0.01, true);
    std::printf("         truth: Chrono Audi 245/40 R18 (PAC2002), %zu synthetic rows; errors are rms over held-out loads 0.6 .. 1.4 x FNOMIN, %% of the peak\n", clean.size());

    const mf62::Params start = start_from("hmmwv_pac2002.tir", truth);
    print_errors("template alone (no fit)", validate(truth, start));

    const tirfit::Result r0 = tirfit::fit(start, clean);
    std::printf("%s", tirfit::report_text(r0).c_str());
    const Errors e0 = validate(truth, r0.params);
    print_errors("fit, noise-free", e0);
    test::check("noise-free: 5 stages ran", r0.stages.size() == 5 && std::all_of(r0.stages.begin(), r0.stages.end(), [](const tirfit::Stage& s) { return s.ran; }));
    test::check("noise-free: Fx rms <= 1.5 % of the peak on held-out loads", e0.fx <= 1.5);
    test::check("noise-free: Fy rms <= 1.5 % of the peak on held-out loads and cambers", e0.fy <= 1.5);
    test::check("noise-free: Mz rms <= 5 % of the peak", e0.mz <= 5.0);
    test::check("noise-free: combined slip Fx and Fy rms <= 4 %", e0.fxc <= 4.0 && e0.fyc <= 4.0);
    test::check("noise-free: peak forces and cornering stiffness within 3 %", e0.peak_fy <= 3.0 && e0.peak_fx <= 3.0 && e0.c_alpha <= 3.0);

    const tirfit::Result r1 = tirfit::fit(start, noisy);
    const Errors e1 = validate(truth, r1.params);
    print_errors("fit, 1 % noise", e1);
    test::check("1 % noise: Fx and Fy rms <= 2.5 % of the peak", e1.fx <= 2.5 && e1.fy <= 2.5);
    test::check("1 % noise: Mz rms <= 6 %, combined <= 5 %", e1.mz <= 6.0 && e1.fxc <= 5.0 && e1.fyc <= 5.0);
    test::check("1 % noise: peak forces and cornering stiffness within 4 %", e1.peak_fy <= 4.0 && e1.peak_fx <= 4.0 && e1.c_alpha <= 4.0);
    test::check("the fit never makes a coefficient leave its bounds (no stage reports more than 3 on a bound)", std::all_of(r1.stages.begin(), r1.stages.end(), [](const tirfit::Stage& s) { return s.at_bounds.size() <= 3; }));
}

// Several different tyres as truth, each started from a different template: the fit does not depend on one lucky pair. Noise-free, pure slip + aligning (the combined stage is covered above).
RS_TEST(tirfit_other_tyres) {
    struct Pair { const char* truth; const char* start; };
    double worst_fx = 0, worst_fy = 0, worst_mz = 0, worst_peak = 0, worst_calpha = 0;
    for (const Pair& pr : {Pair{"sedan_pac2002.tir", "hmmwv_pac2002.tir"}, Pair{"suv_pac2002.tir", "audi_245_40R18_pac2002.tir"}, Pair{"classic_185_80R14_pac2002.tir", "polaris_pac2002.tir"}, Pair{"hmmwv_pac2002.tir", "classic_185_80R14_pac2002.tir"}}) {
        const mf62::Params truth = load(pr.truth);
        Grid g;
        g.loads = {0.5, 0.75, 1.0, 1.25, 1.5};
        const tirfit::Result r = tirfit::fit(start_from(pr.start, truth), synth(truth, g, 0.0, true));
        const Errors e = validate(truth, r.params);
        std::printf("         truth %-30s started from %-28s ", pr.truth, pr.start);
        print_errors("", e);
        worst_fx = std::max(worst_fx, e.fx); worst_fy = std::max(worst_fy, e.fy); worst_mz = std::max(worst_mz, e.mz); worst_peak = std::max({worst_peak, e.peak_fy, e.peak_fx}); worst_calpha = std::max(worst_calpha, e.c_alpha);
    }
    test::check_range("worst Fx rms over the four pairs", worst_fx, 0.0, 2.0, "%");
    test::check_range("worst Fy rms over the four pairs", worst_fy, 0.0, 2.0, "%");
    test::check_range("worst Mz rms over the four pairs", worst_mz, 0.0, 6.0, "%");
    test::check_range("worst peak-force error over the four pairs", worst_peak, 0.0, 3.0, "%");
    test::check_range("worst initial cornering stiffness error over the four pairs (the weakest-determined quantity; observed 3.5 %)", worst_calpha, 0.0, 5.0, "%");
}

// Honest about missing data: a data set without camber, pressure or aligning moment must say so and leave those coefficients at the template's values.
RS_TEST(tirfit_missing_data) {
    const mf62::Params truth = load("audi_245_40R18_pac2002.tir");
    Grid g;
    g.loads = {0.75, 1.0, 1.25};
    g.gammas = {0.0};
    std::vector<tirfit::Sample> d = synth(truth, g, 0.0, false);
    for (auto& s : d) s.mz = tirfit::kNaN;  // no aligning moment measured
    const mf62::Params start = start_from("hmmwv_pac2002.tir", truth);
    const tirfit::Result r = tirfit::fit(start, d);
    bool notes_camber = false, mz_skipped = false, combined_skipped = false;
    for (const auto& n : r.notes) notes_camber = notes_camber || n.find("no camber variation") != std::string::npos;
    for (const auto& s : r.stages) {
        if (s.name == "mz0") mz_skipped = !s.ran;
        if (s.name == "fx" || s.name == "fy") combined_skipped = !s.ran;
    }
    test::check("a data set without camber says so", notes_camber);
    test::check("no Mz measured: the aligning stage is skipped, not faked", mz_skipped);
    test::check("no combined-slip rows: the combined stages are skipped", combined_skipped);
    test::check("camber coefficients keep the template's values", r.params.pdy3 == start.pdy3 && r.params.pky3 == start.pky3 && r.params.phy3 == start.phy3);
    test::check("aligning coefficients keep the template's values", r.params.qdz1 == start.qdz1 && r.params.qbz1 == start.qbz1);
    std::set<std::string> fitted = r.fitted_keys;
    test::check("pure-slip coefficients were fitted", fitted.count("PDX1") && fitted.count("PDY1") && fitted.count("PKY1"));
    const Errors e = validate(truth, r.params);
    test::check_range("pure-slip Fy still within 2 % at zero camber", [&] {
        double s = 0, pk = 0; int n = 0;
        for (double l : {0.6, 0.9, 1.1, 1.4}) for (int i = -24; i <= 24; i += 2) {
            const auto a = tyre_at(truth, l * truth.fnomin, 0, 0.01 * i, 0), b = tyre_at(r.params, l * truth.fnomin, 0, 0.01 * i, 0);
            s += (a.fy - b.fy) * (a.fy - b.fy); pk = std::max(pk, std::abs(a.fy)); ++n;
        }
        return 100.0 * std::sqrt(s / n) / pk;
    }(), 0.0, 2.0, "%");
    (void)e;
}

RS_TEST(tirfit_csv_and_writer) {
    // csv: units in the header, semicolons, degrees, kPa, SAE angle sign, comments, blank lines
    const std::string csv = "# a comment\nFz [N];SA [deg];IA [deg];P [kPa];Fy [N];Mz [Nm]\n\n3000;2;0;220;-1500;12.5\n4000;-4;1;200;2500;-20\n";
    std::vector<tirfit::Sample> d;
    std::string err;
    test::check("csv: parses", tirfit::read_csv(csv, d, err) && d.size() == 2);
    if (d.size() == 2) {
        test::check_range("csv: 2 deg -> rad", d[0].alpha, 0.03490, 0.03491, "rad");
        test::check_range("csv: kPa -> Pa", d[1].pressure, 199999.0, 200001.0, "Pa");
        test::check("csv: missing channels are NaN, present ones kept", std::isnan(d[0].fx) && d[0].fy == -1500.0 && d[1].mz == -20.0);
    }
    std::vector<tirfit::Sample> flipped;
    tirfit::read_csv(csv, flipped, err, -1.0);
    test::check("csv: angle sign -1 flips slip angle and camber, not forces", flipped.size() == 2 && flipped[0].alpha < 0 && flipped[1].gamma < 0 && flipped[0].fy == -1500.0);
    std::vector<tirfit::Sample> bad;
    test::check("csv: a header without Fz is refused", !tirfit::read_csv("alpha,fy\n0.1,100\n", bad, err));
    test::check("csv: a non-number is refused with its line", !tirfit::read_csv("fz,fy\n3000,abc\n", bad, err) && err.find("line 2") != std::string::npos);
    test::check("csv: a zero load is refused", !tirfit::read_csv("fz,fy\n0,100\n", bad, err));
    test::check("csv: a unit it does not know is refused", !tirfit::read_csv("fz [lbf],fy\n600,100\n", bad, err));
    {
        std::vector<tirfit::Sample> u;
        test::check("csv: km/h, bar and a degree-suffixed name are converted", tirfit::read_csv("fz,vx [km/h],p [bar],alpha_deg,fy\n3000,36,2.2,5,100\n", u, err) && u.size() == 1 && std::abs(u[0].vx - 10.0) < 1e-9 && std::abs(u[0].pressure - 220000.0) < 1e-6 && std::abs(u[0].alpha - 0.0872665) < 1e-6);
    }

    // every coefficient name a stage uses exists in rs::mf62
    bool all_known = true;
    for (const char* st : {"fx0", "fy0", "mz0", "fx", "fy"})
        for (bool cam : {false, true})
            for (bool pr : {false, true})
                for (auto v : {mf62::Version::Mf52, mf62::Version::Mf61, mf62::Version::Mf62})
                    for (const std::string& k : tirfit::stage_keys(st, cam, pr, v)) {
                        double x;
                        if (!tirfit::get_coefficient(mf62::Params{}, k, x)) { all_known = false; std::printf("         unknown coefficient %s in stage %s\n", k.c_str(), st); }
                    }
    test::check("every coefficient a fit stage names is one rs::mf62 reads", all_known);

    // writer: changed coefficients rewritten in place, new ones appended, everything else untouched, header as comments
    std::string text, e2;
    {
        FILE* f = std::fopen(test::data_path("tires/audi_245_40R18_pac2002.tir").c_str(), "rb");
        char buf[4096];
        std::size_t n;
        while (f && (n = std::fread(buf, 1, sizeof buf, f)) > 0) text.append(buf, n);
        if (f) std::fclose(f);
    }
    mf62::Params before, after;
    mf62::parse_tir(text, before, e2);
    after = before;
    after.pdx1 = 1.2345; after.pky1 = before.pky1 * 1.1; after.ppx1 = 0.25;  // PPX1 is not in the Chrono file
    const std::string out = tirfit::write_tir(text, before, after, {"PCX1"}, {"header line one", "header line two"});
    mf62::Params round;
    test::check("writer: the result parses", mf62::parse_tir(out, round, e2));
    test::check("writer: changed coefficients are in the file", std::abs(round.pdx1 - 1.2345) < 1e-9 && std::abs(round.pky1 - after.pky1) < 1e-9 * std::abs(after.pky1));
    test::check("writer: a coefficient the template did not list is appended", std::abs(round.ppx1 - 0.25) < 1e-12 && out.find("[OPENGRID_FITTED]") != std::string::npos);
    test::check("writer: untouched coefficients are unchanged", round.pdy1 == before.pdy1 && round.qbz1 == before.qbz1 && round.fnomin == before.fnomin && round.fittyp == before.fittyp);
    test::check("writer: the header is written as '$' comment lines on top", out.rfind("$ header line one\n$ header line two\n", 0) == 0);
}

}  // namespace
